def spacial_surface_friction(x,y):
    out = 0. * np.ones_like(x)
    Xi = []
    Di = []
    for i in range(3):
        for j in range(10):
            Xi.append([i *20- 50, j * 20 -70 ])
            Di.append([5])
    for i, xi in enumerate(Xi):
        r = np.sqrt((x-xi[0])**2 + (y-xi[1])**2)
        out += np.where(r &lt; Di[i], friction_strength * np.ones_like(x), 0.0 * np.ones_like(x))
    return out

