class MyModel(NumericalShallowMomentsTopo):

    def update_variables(self):
        Q = self.variables
        h = Q[1]
        Qout = ZArray(Q)
        h = conditional(h &lt;= 0, 0, h)
        Qout[1] = h
        eps = self.parameters.eps
        factor = h / (h + eps*100.)
        for i in range(2, self.n_variables):
            Qout[i] *= factor
        return Qout


    def update_aux_variables(self):
        Q = self.variables
        Qaux = ZArray(self.aux_variables)
        eps = self.parameters.eps
        Qaux[0] = Q[1] / (Q[1]**2 + eps)
        return ZArray(Qaux)

    def source(self):
        out = Matrix([0 for i in range(self.n_variables)])
        # out += self.newtonian()
        # out += self.slip_mod()
        # out += self.slip()
        out += self.surface_friction()
        return out



