\(\displaystyle \left[\begin{matrix}\operatorname{conditional}{\left(q_{1} &gt; eps,0,0 \right)} & \operatorname{conditional}{\left(q_{1} &gt; eps,\frac{n_{0} q_{2} + n_{1} q_{4}}{q_{1}},0 \right)} & \operatorname{conditional}{\left(q_{1} &gt; eps,\frac{n_{0} q_{2} + n_{1} q_{4} - \sqrt{ez g n_{0}^{2} q_{1}^{3} + ez g n_{1}^{2} q_{1}^{3} + n_{0}^{2} q_{3}^{2} + 2 n_{0} n_{1} q_{3} q_{5} + n_{1}^{2} q_{5}^{2}}}{q_{1}},0 \right)} & \operatorname{conditional}{\left(q_{1} &gt; eps,\frac{n_{0} q_{2} + n_{1} q_{4} + \sqrt{ez g n_{0}^{2} q_{1}^{3} + ez g n_{1}^{2} q_{1}^{3} + n_{0}^{2} q_{3}^{2} + 2 n_{0} n_{1} q_{3} q_{5} + n_{1}^{2} q_{5}^{2}}}{q_{1}},0 \right)} & \operatorname{conditional}{\left(q_{1} &gt; eps,\frac{n_{0} q_{2} - \frac{\sqrt{3} n_{0} q_{3}}{3} + n_{1} q_{4} - \frac{\sqrt{3} n_{1} q_{5}}{3}}{q_{1}},0 \right)} & \operatorname{conditional}{\left(q_{1} &gt; eps,\frac{n_{0} q_{2} + \frac{\sqrt{3} n_{0} q_{3}}{3} + n_{1} q_{4} + \frac{\sqrt{3} n_{1} q_{5}}{3}}{q_{1}},0 \right)}\end{matrix}\right]\)





