        amrex::SmallMatrix&lt;amrex::Real,2,1&gt; const& Qaux,
        amrex::SmallMatrix&lt;amrex::Real,8,1&gt; const& p) noexcept
    {
    amrex::Real t0 = (1.0/2.0)*p(1, 0)*p(0, 0)*amrex::Math::powi&lt;2&gt;(Q(1, 0));
    amrex::SmallMatrix&lt;amrex::Real,12,1&gt; res;
    res(0, 0) = 0;
    res(1, 0) = 0;
    res(2, 0) = 0;
    res(3, 0) = 0;
    res(4, 0) = t0;
    res(5, 0) = 0;
    res(6, 0) = 0;
    res(7, 0) = 0;
    res(8, 0) = 0;
    res(9, 0) = t0;
    res(10, 0) = 0;
    res(11, 0) = 0;
    return res;
    }


