    amrex::Real t9 = (1.0/3.0)*std::pow(3, 1.0/2.0);
    amrex::Real t10 = t3*t9;
    amrex::Real t11 = t4*t9;
    amrex::SmallMatrix&lt;amrex::Real,6,1&gt; res;
    res(0, 0) = ((t0) ? (0) : (0));
    res(1, 0) = ((t0) ? (t1*t2) : (0));
