    T t5 = t4/std::max(9.9999999999999995e-7, Q_plus[1]);
    T v_arg_0[] = { t0, t2, Q_minus[2]*t3, Q_minus[3]*t3, Q_minus[4]*t3, Q_minus[5]*t3 };
    T v_arg_1[] = { (1.0 / std::pow(p[2] + t2, 1)), Qaux_minus[1] };
