    amrex::Real t3 = std::pow(p(2, 0), 1.0/2.0)*std::pow(p(0, 0), 1.0/2.0)*std::pow(Q(1, 0), 3.0/2.0)*std::pow(amrex::Math::powi&lt;2&gt;(n(0, 0)) + amrex::Math::powi&lt;2&gt;(n(1, 0)), 1.0/2.0);
