    AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE
    static amrex::SmallMatrix&lt;amrex::Real,1,1&gt; update_aux_variables(
        amrex::SmallMatrix&lt;amrex::Real,4,1&gt; const& Q,
        amrex::SmallMatrix&lt;amrex::Real,1,1&gt; const& Qaux,
